fn filter_short_words(words: &Vec[Str], max_len: Int) -> Vec[Str] {
  let result: Vec[Str] = Vec[Str].new();
  let i = 0;
  while i < words.len() {
    let w = match words.get(i) { Some(v) => v, None => "" };
    if string.str_len(w) <= max_len {
      result.push(w);
    }
    i = i + 1;
  }
  return result;
}

fn add_prefix(words: &Vec[Str], prefix: Str) -> Vec[Str] {
  let result: Vec[Str] = Vec[Str].new();
  let i = 0;
  while i < words.len() {
    let w = match words.get(i) { Some(v) => v, None => "" };
    result.push(prefix + w);
    i = i + 1;
  }
  return result;
}

fn main() -> Int {
  let words: Vec[Str] = Vec[Str].new();
  words.push("hi"); words.push("elephant"); words.push("ok"); words.push("butterfly");

  let short = filter_short_words(&words, 3);
  let labeled = add_prefix(&short, "short:");

  let i = 0;
  while i < labeled.len() {
    let w = match labeled.get(i) { Some(v) => v, None => "" };
    io.println(w);
    i = i + 1;
  }
  return 0;
}
